import { Protocol } from '@uniswap/router-sdk';
import { Pair } from '@uniswap/v2-sdk';
import { Pool as V3Pool } from '@uniswap/v3-sdk';
import { Pool as V4Pool } from '@uniswap/v4-sdk';
import { getAddress } from '../../../../util';
/**
 * Class defining the route to cache
 *
 * @export
 * @class CachedRoute
 */
export class CachedRoute {
  /**
   * @param route
   * @param percent
   */
  constructor({
    route,
    percent
  }) {
    // Hashing function copying the same implementation as Java's `hashCode`
    // Sourced from: https://gist.github.com/hyamamoto/fd435505d29ebfa3d9716fd2be8d42f0?permalink_comment_id=4613539#gistcomment-4613539
    this.hashCode = str => [...str].reduce((s, c) => Math.imul(31, s) + c.charCodeAt(0) | 0, 0);
    this.route = route;
    this.percent = percent;
  }
  get protocol() {
    return this.route.protocol;
  }
  get currencyIn() {
    return this.route.input;
  }
  get currencyOut() {
    return this.route.output;
  }
  get routePath() {
    switch (this.protocol) {
      case Protocol.V4:
        return this.route.pools.map(pool => `[V4]${getAddress(pool.token0)}/${getAddress(pool.token1)}/${pool.fee}/${pool.hooks}/${pool.tickSpacing}`).join('->');
      case Protocol.V3:
        return this.route.pools.map(pool => `[V3]${pool.token0.address}/${pool.token1.address}/${pool.fee}`).join('->');
      case Protocol.V2:
        return this.route.pairs.map(pair => `[V2]${pair.token0.address}/${pair.token1.address}`).join('->');
      case Protocol.MIXED:
        return this.route.pools.map(pool => {
          if (pool instanceof V4Pool) {
            // TODO: ROUTE-217 - Support native currency routing in V4
            return `[V4]${getAddress(pool.token0)}/${getAddress(pool.token1)}/${pool.fee}/${pool.hooks}/${pool.tickSpacing}`;
          } else if (pool instanceof V3Pool) {
            return `[V3]${pool.token0.address}/${pool.token1.address}/${pool.fee}`;
          } else if (pool instanceof Pair) {
            return `[V2]${pool.token0.address}/${pool.token1.address}`;
          } else {
            throw new Error(`Unsupported pool type ${JSON.stringify(pool)}`);
          }
        }).join('->');
      default:
        throw new Error(`Unsupported protocol ${this.protocol}`);
    }
  }
  get routeId() {
    return this.hashCode(this.routePath);
  }
}
